/* libbacktrace's configuration, written by hand instead of generated by its configure script
 * (runtime/THIRD_PARTY.md). One file for every Tier 1 target, keyed by the compiler's predefined
 * macros; the executable format decides which reader is compiled (RuntimeLayout.cs). */
#ifndef LYR_BACKTRACE_CONFIG_H
#define LYR_BACKTRACE_CONFIG_H

/* Every Tier 1 target is 64-bit and has the GCC atomic builtins (clang via zig cc). */
#define HAVE_ATOMIC_FUNCTIONS 1
#define HAVE_SYNC_FUNCTIONS 1
#define HAVE_DECL_STRNLEN 1
#define HAVE_GETIPINFO 1
#define BACKTRACE_ELF_SIZE 64
#define BACKTRACE_XCOFF_SIZE 64

#if defined(__linux__)
#  ifndef _GNU_SOURCE
#    define _GNU_SOURCE 1
#  endif
#  define HAVE_DL_ITERATE_PHDR 1
#  define HAVE_LINK_H 1
#  define HAVE_DECL_GETPAGESIZE 1
#  define HAVE_FCNTL 1
#  define HAVE_LSTAT 1
#  define HAVE_READLINK 1
#elif defined(__APPLE__)
#  ifndef _DARWIN_C_SOURCE
#    define _DARWIN_C_SOURCE 1
#  endif
#  define HAVE_MACH_O_DYLD_H 1
#  define HAVE_DECL_GETPAGESIZE 1
#  define HAVE_FCNTL 1
#  define HAVE_LSTAT 1
#  define HAVE_READLINK 1
#elif defined(_WIN32)
#  define HAVE_WINDOWS_H 1
#  define HAVE_TLHELP32_H 1
#  define HAVE_DECL__PGMPTR 1
#else
#  error "libbacktrace: no configuration for this target"
#endif

#endif
